package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/owner/dashboard") @PreAuthorize("hasAnyRole('OWNER','ADMIN','SALESPERSON')")
public class OwnerDashboardController{private final JdbcClient db;public OwnerDashboardController(JdbcClient db){this.db=db;}
 @GetMapping Map<String,Object> dashboard(@AuthenticationPrincipal CurrentUser u,@RequestParam(defaultValue="TODAY")String period){CustomerController.tenant(u);LocalDate end=LocalDate.now().plusDays(1);LocalDate start=switch(period){case"7_DAYS"->end.minusDays(7);case"30_DAYS"->end.minusDays(30);default->end.minusDays(1);};var result=new LinkedHashMap<String,Object>();result.put("period",period);result.put("rangeStart",start);result.put("rangeEnd",end.minusDays(1));
 result.put("summary",db.sql("select coalesce(sum(total),0) sales,coalesce(sum(amount_paid),0) collected,coalesce(sum(total-amount_paid),0) outstanding,count(*) orders,count(*) filter(where delivered_at is null and fulfillment_status<>'CANCELLED') open_orders from amcservice.orders where tenant_id=:t and created_at>=:start and created_at<:end").param("t",u.tenantId()).param("start",start).param("end",end).query().singleRow());
 result.put("daily",db.sql("select d::date day,coalesce(sum(o.total),0) sales from generate_series(cast(:start as date),cast(:last as date),interval '1 day') d left join amcservice.orders o on o.tenant_id=:t and o.created_at>=d and o.created_at<d+interval '1 day' group by d order by d").param("t",u.tenantId()).param("start",start).param("last",end.minusDays(1)).query().listOfRows());
 result.put("popular",db.sql("select oi.description name,sum(oi.quantity) quantity,sum((oi.unit_price-oi.discount)*oi.quantity) revenue from amcservice.order_items oi join amcservice.orders o on o.id=oi.order_id where o.tenant_id=:t and o.created_at>=:start and o.created_at<:end and o.fulfillment_status<>'CANCELLED' group by oi.description order by quantity desc,revenue desc limit 5").param("t",u.tenantId()).param("start",start).param("end",end).query().listOfRows());
 result.put("recentOrders",db.sql("select o.id,o.bill_number,c.name customer_name,o.total,o.amount_paid,o.fulfillment_status,o.due_date,o.created_at from amcservice.orders o join amcservice.customers c on c.id=o.customer_id where o.tenant_id=:t order by o.created_at desc limit 6").param("t",u.tenantId()).query().listOfRows());return result;}}
